        if (capturePumping) return

        val alpha = (Prefs.overlayOpacity().coerceIn(0.1f, 0.9f) * 255).toInt()
        dimPaint.color = Color.argb(alpha, 4, 8, 20)

        // Затемнение вокруг рамки.
        canvas.drawRect(0f, 0f, viewW, toolbarRect.bottom, dimPaint)
        canvas.drawRect(0f, toolbarRect.bottom, frame.left, frame.top, dimPaint)
        canvas.drawRect(frame.right, toolbarRect.bottom, viewW, frame.bottom, dimPaint)
        canvas.drawRect(0f, frame.bottom, viewW, viewH, dimPaint)
        canvas.drawRect(frame.left, frame.bottom, frame.right, viewH, dimPaint)
        canvas.drawRect(0f, toolbarRect.bottom, frame.left, viewH, dimPaint)

        // Рамка захвата.
        canvas.drawRoundRect(frame, dp(10f), dp(10f), borderPaint)
        drawHandles(canvas)

        // Тулбар.
        canvas.drawRoundRect(toolbarRect, dp(10f), dp(10f), toolbarPaint)
        drawToolbarButtons(canvas)

        // Панель результата.
        canvas.drawRoundRect(panelRect, dp(10f), dp(10f), panelPaint)
        drawResultPanel(canvas)
    }

    private fun drawToolbarButtons(canvas: Canvas) {
        for ((rect, btn) in buttons) {
            btnPaint.color = if (btn == pressedBtn) Color.parseColor("#FF8A65") else Color.WHITE
            btnPaint.textAlign = Paint.Align.CENTER
            canvas.drawText(btn.label, rect.centerX(), rect.centerY() + dp(4f), btnPaint)
        }
    }

    private fun drawHandles(canvas: Canvas) {
        val hs = dp(16f)
        val half = hs / 2
        for ((cx, cy) in handlePositions()) {
            canvas.drawRect(RectF(cx - half, cy - half, cx + half, cy + half), handlePaint)
        }
    }

    private fun handlePositions(): List<Pair<Float, Float>> {
        val midX = (frame.left + frame.right) / 2
        val midY = (frame.top + frame.bottom) / 2
        return listOf(
            frame.left to frame.top,
            midX to frame.top,
            frame.right to frame.top,
            frame.left to midY,
            frame.right to midY,
            frame.left to frame.bottom,
            midX to frame.bottom,
            frame.right to frame.bottom,
        )
    }

    private fun drawResultPanel(canvas: Canvas) {
        val pad = dp(10f)
        statusPaint.textAlign = Paint.Align.LEFT
        canvas.drawText(
            if (scanning) "Распознаю текст…" else statusText.ifBlank { "Готово" },
            pad,
            panelRect.top + dp(18f),
            statusPaint,
        )
        val maxW = (panelRect.width() - pad * 2).toInt()
        val text = resultText
        if (text.isNotBlank()) {
            val lines = wrapText(resultPaint, text, maxW)
            val lineH = resultPaint.textSize * 1.25f
            val available = panelRect.height() - dp(34f)
            val visible = (available / lineH).toInt().coerceAtLeast(1)
            val maxScroll = max(0, lines.size - visible)
            scrollLines = scrollLines.coerceIn(0, maxScroll)
            var y = panelRect.top + dp(34f) + lineH
            for (i in scrollLines until min(scrollLines + visible, lines.size)) {
                canvas.drawText(lines[i], pad, y, resultPaint)
                y += lineH
            }
        }
    }

    private fun wrapText(paint: Paint, text: String, maxW: Int): List<String> {
        val words = text.split(" ")
        val lines = ArrayList<String>()
        var line = StringBuilder()
        for (word in words) {
            val probe = if (line.isEmpty()) word else "$line $word"
            if (paint.measureText(probe) <= maxW) {
                line = StringBuilder(probe)
            } else {
                if (line.isNotEmpty()) lines += line.toString()
                line = StringBuilder(word)
                while (line.isNotEmpty() && paint.measureText(line.toString()) > maxW) {
                    var cut = line.length
                    while (cut > 1 && paint.measureText(line.substring(0, cut)) > maxW) cut--
                    lines += line.substring(0, cut)
                    line = StringBuilder(line.substring(cut))
                }
            }
        }
        if (line.isNotEmpty()) lines += line.toString()
        return lines
    }

    override fun onTouchEvent(event: MotionEvent): Boolean {
        val x = event.x
        val y = event.y
        when (event.actionMasked) {
            MotionEvent.ACTION_DOWN -> return onDown(x, y)
            MotionEvent.ACTION_MOVE -> { onMove(x, y); return true }
            MotionEvent.ACTION_UP, MotionEvent.ACTION_CANCEL -> {
                onUp()
                return true
            }
        }
        return true
    }

    private fun onDown(x: Float, y: Float): Boolean {
        touchX = x
        touchY = y
        startFrame.set(frame)
        lastPanelY = y

        for ((rect, btn) in buttons) {
            if (rect.contains(x, y)) {
                pressedBtn = btn
                invalidate()
                return true
            }
        }
        if (panelRect.contains(x, y) && resultText.isNotBlank()) {
            mode = Mode.SCROLL
            return true
        }
        val handle = findHandle(x, y)
        if (handle != null) {
            mode = Mode.CORNER_RESIZE
            handleIndex = handle
            return true
        }
        if (frame.contains(x, y)) {
            mode = Mode.MOVE
            return true
        }
        return true
    }

    private var handleIndex = -1

    private fun findHandle(x: Float, y: Float): Int? {
        val r = dp(20f)
        for ((i, pos) in handlePositions().withIndex()) {
            if (Math.abs(x - pos.first) <= r && Math.abs(y - pos.second) <= r) return i
        }
        return null
    }

    private fun onMove(x: Float, y: Float) {
        val dx = x - touchX
        val dy = y - touchY
        when (mode) {
            Mode.MOVE -> {
                val newLeft = startFrame.left + dx
                val newTop = startFrame.top + dy
                val newRight = startFrame.right + dx
                val newBottom = startFrame.bottom + dy
                val shiftX = newLeft.coerceAtLeast(dp(6f)) - newLeft
                val fixedLeft = newLeft + shiftX
                val fixedRight = newRight + shiftX
                frame.set(
                    fixedLeft,
                    newTop.coerceIn(toolbarRect.bottom + dp(6f), panelRect.top - frame.height() - dp(6f)),
                    fixedRight,
                    newTop.coerceIn(toolbarRect.bottom + dp(6f), panelRect.top - frame.height() - dp(6f)) + frame.height(),
                )
                invalidate()
            }
            Mode.CORNER_RESIZE -> {
                resizeTo(dx, dy)
                invalidate()
            }
            Mode.SCROLL -> {
                val lineH = resultPaint.textSize * 1.25f
                val delta = (y - lastPanelY) / lineH
                scrollLines += delta.toInt()
                lastPanelY = y
                invalidate()
            }
            else -> Unit
        }
        touchX = x
        touchY = y
    }

    private fun resizeTo(dx: Float, dy: Float) {
        val minSide = dp(48f)
        val l = frame.left
        val t = frame.top
        val r = frame.right
        val b = frame.bottom
        when (handleIndex) {
            0 -> { val nl = (startFrame.left + dx).coerceAtMost(r - minSide); frame.set(nl, (startFrame.top + dy).coerceAtMost(b - minSide), r, b) }
            1 -> frame.set(l, (startFrame.top + dy).coerceAtMost(b - minSide), r, b)
            2 -> { val nr = (startFrame.right + dx).coerceAtLeast(l + minSide); frame.set(l, (startFrame.top + dy).coerceAtMost(b - minSide), nr, b) }
            3 -> { val nl = (startFrame.left + dx).coerceAtMost(r - minSide); frame.set(nl, t, r, b) }
            4 -> { val nr = (startFrame.right + dx).coerceAtLeast(l + minSide); frame.set(l, t, nr, b) }
            5 -> { val nl = (startFrame.left + dx).coerceAtMost(r - minSide); val nb = (startFrame.bottom + dy).coerceAtLeast(t + minSide); frame.set(nl, t, r, nb) }
            6 -> frame.set(l, t, r, (startFrame.bottom + dy).coerceAtLeast(t + minSide))
            7 -> { val nb = (startFrame.bottom + dy).coerceAtLeast(t + minSide); frame.set(l, t, (startFrame.right + dx).coerceAtLeast(l + minSide), nb) }
        }
        clampFrame()
    }

    private fun onUp() {
        val btn = pressedBtn
        if (btn != null) {
            perform(btn)
        }
        pressedBtn = null
        mode = Mode.NONE
        callback.onFrameChanged(bean())
        invalidate()
    }

    private fun perform(btn: Btn) {
        when (btn) {
            Btn.SCAN -> callback.onScan()
            Btn.SPEAK -> callback.onSpeak()
            Btn.VOICE -> callback.onCycleVoice()
            Btn.OPAQUE -> callback.onOpacity(0.08f)
            Btn.HIDE -> callback.onPassThrough()
            Btn.EXIT -> callback.onExit()
        }
    }

    private fun bean(): RectFBean = RectFBean(
        left = (frame.left / viewW).coerceIn(0f, 1f),
        top = (frame.top / viewH).coerceIn(0f, 1f),
        right = (frame.right / viewW).coerceIn(0f, 1f),
        bottom = (frame.bottom / viewH).coerceIn(0f, 1f),
    )

    fun resetFrame() {
        frame.set(viewW * 0.06f, toolbarRect.bottom + dp(24f), viewW * 0.94f, viewW * 0.94f * 0.55f + toolbarRect.bottom)
        clampFrame()
        invalidate()
    }
}

package com.yomikai.overlayreader

import android.app.Notification
import android.app.NotificationChannel
import android.app.NotificationManager
import android.app.PendingIntent
import android.app.Service
import android.content.Context
import android.content.Intent
import android.content.pm.ServiceInfo
import android.graphics.Bitmap
import android.graphics.Canvas
import android.graphics.Color
import android.graphics.Paint
import android.graphics.PixelFormat
import android.graphics.Rect
import android.media.projection.MediaProjection
import android.media.projection.MediaProjectionManager
import android.os.Build
import android.os.IBinder
import android.util.Log
import android.view.Gravity
import android.view.MotionEvent
import android.view.View
import android.view.WindowManager
import com.yomikai.overlayreader.ocr.OcrManager
import com.yomikai.overlayreader.ocr.OcrResult
import com.yomikai.overlayreader.tts.ReaderTts
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.SupervisorJob
import kotlinx.coroutines.cancel
import kotlinx.coroutines.launch
import kotlinx.coroutines.withContext

/**
 * Фоновый сервис читалки: полноэкранный оверлей с рамкой выбора, захват экрана
 * через MediaProjection, распознавание (онлайн/локально) и озвучка.
 *
 * Дополнительно — маленький «пузырь» управления (кнопка-точка): он всегда
 * доступен и переключает пропуск касаний (читалка скрыта / читалка видна).
 */
class OverlayReaderService : Service() {

    private val scope = CoroutineScope(SupervisorJob() + Dispatchers.Main.immediate)

    private lateinit var wm: WindowManager
    private var overlay: OverlayView? = null
    private var bubbleView: View? = null
    private var bubbleParams: WindowManager.LayoutParams? = null
    private var overlayParams: WindowManager.LayoutParams? = null

    private var projection: MediaProjection? = null
    private var capture: CaptureEngine? = null
    private val ocrManager = OcrManager()
    private var tts: ReaderTts? = null

    private val screenMetrics = android.util.DisplayMetrics()

    // ----------------------------------------------------------- lifecycle

    override fun onCreate() {
        super.onCreate()
        wm = getSystemService(Context.WINDOW_SERVICE) as WindowManager
        wm.defaultDisplay.getRealMetrics(screenMetrics)
        Prefs.init(this)
        createNotification(
            "Overlay Reader активен",
            "Читалка работает поверх экрана",
        )
    }

    override fun onStartCommand(intent: Intent?, flags: Int, startId: Int): Int {
        when (intent?.action) {
            ACTION_STOP -> stopEverything()
            else -> startReader(intent)
        }
        return START_NOT_STICKY
    }

    private fun startReader(intent: Intent?) {
        if (projection != null) return
        val mediaProjectionManager = getSystemService(Context.MEDIA_PROJECTION_SERVICE) as MediaProjectionManager
        @Suppress("DEPRECATION")
        val data = intent?.getParcelableExtra<Intent>(EXTRA_DATA) ?: return
        val resultCode = intent.getIntExtra(EXTRA_RESULT_CODE, 0)

        val proj = mediaProjectionManager.getMediaProjection(resultCode, data) ?: return
        projection = proj
        proj.registerCallback(
            object : MediaProjection.Callback() {
                override fun onStop() {
                    stopEverything()
                }
            },
            null,
        )

        capture = CaptureEngine(this, proj)
        tts = ReaderTts(this).also { it.init(null) }

        val overlayView = OverlayView(this, overlayCallback)
        addOverlayWindow(overlayView)
        addBubbleWindow()
        overlay = overlayView
    }

    private val overlayCallback = object : OverlayView.Callback {
        override fun onScan() = scan()
        override fun onSpeak() {
            val text = overlay?.resultText.orEmpty()
            if (text.isNotBlank()) tts?.speak(currentRegions())
        }

        override fun onCycleVoice() {
            val count = tts?.availableVoiceCount() ?: 0
            val index = tts?.cycleVoice() ?: 0
            overlay?.statusText = "Голос ${index + 1}/$count"
            overlay?.invalidate()
        }

        override fun onOpacity(delta: Float) {
            val next = (Prefs.overlayOpacity() + delta)
            Prefs.setOverlayOpacity(next.coerceIn(0.12f, 0.85f))
            overlay?.invalidate()
        }

        override fun onPassThrough() = setPassthrough(true)

        override fun onResetFrame() {
            overlay?.resetFrame()
        }

        override fun onExit() = stopEverything()

        override fun onFrameChanged(f: RectFBean) {
            Prefs.saveFrame(f)
        }
    }

    // ----------------------------------------------------------- scanning

    private var lastRegions: List<com.yomikai.overlayreader.ocr.OcrRegion> = emptyList()

    private fun currentRegions(): List<com.yomikai.overlayreader.ocr.OcrRegion> = lastRegions

    private fun scan() {
        val overlayView = overlay ?: return
        val capturer = capture ?: run {
            overlayView.statusText = "Захват недоступен"
            overlayView.invalidate()
            return
        }
        wm.defaultDisplay.getRealMetrics(screenMetrics)
        val screenW = screenMetrics.widthPixels
        val screenH = screenMetrics.heightPixels
        if (screenW <= 0 || screenH <= 0) {
            overlayView.statusText = "Ошибка захвата экрана"
            overlayView.invalidate()
            return
        }

        scope.launch {
            overlayView.scanning = true
            overlayView.statusText = "Распознаю текст…"
            overlayView.invalidate()

            // Точные экранные координаты окна оверлея: на ряде устройств окно
            // APPLICATION_OVERLAY смещено вниз от статусбара, поэтому пересчёт
            // «доля → пиксель» идёт через локальные координаты окна.
            val loc = IntArray(2)
            overlayView.getLocationOnScreen(loc)
            val frameBean = Prefs.frame()
            val vw = overlayView.width
            val vh = overlayView.height
            val rect = Rect(
                loc[0] + (frameBean.left * vw).toInt(),
                loc[1] + (frameBean.top * vh).toInt(),
                loc[0] + (frameBean.right * vw).toInt(),
                loc[1] + (frameBean.bottom * vh).toInt(),
            )
            Log.i(TAG, "scan region=$rect overlaySize=${vw}x$vh origin=${loc[0]},${loc[1]}")

            // Оверлей держим видимым и «прокачиваем» его перерисовку: это заставляет
            // компоновщик непрерывно выдавать кадры, и VirtualDisplay видит их
            // даже на статичном экране. Панели оверлея в кадр не попадут
            // (во время прокачки они не рисуются).
            val wasHidden = overlayView.visibility != View.VISIBLE
            if (wasHidden) setPassthrough(false)
            overlayView.beginCapturePump()
            val bitmap: Bitmap? = withContext(Dispatchers.Default) {
                runCatching {
                    Thread.sleep(250)
                    capturer.capture(rect)
                }.getOrNull()
            }
            overlayView.endCapturePump()
            setPassthrough(wasHidden)

            if (bitmap == null) {
                overlayView.scanning = false
                overlayView.statusText = "Не удалось получить кадр"
                overlayView.invalidate()
                Log.e(TAG, "capture returned null for $rect")
                return@launch
            }

            val result: OcrResult = try {
                ocrManager.recognize(bitmap, Prefs.ocrMode() ?: "auto")
            } catch (e: Exception) {
                Log.e(TAG, "OCR failed", e)
                OcrResult.empty()
            } finally {
                if (!bitmap.isRecycled) bitmap.recycle()
            }
            Log.i(TAG, "OCR result: ${result.regions.size} regions, text='${result.text.take(80)}'")

            overlayView.scanning = false
            lastRegions = result.regions
            if (result.text.isBlank()) {
                overlayView.resultText = ""
                overlayView.statusText =
                    if (Prefs.ocrMode() == "auto") "Текст не распознан (проверьте сеть)"
                    else "Текст не распознан"
            } else {
                overlayView.resultText = result.text
                overlayView.statusText = "${result.regions.size} реплик(и) · движок ${engineLabel()}"
            }
            overlayView.invalidate()

            if (Prefs.autoTts() && result.regions.isNotEmpty()) {
                tts?.speak(result.regions)
            }
        }
    }

    private fun engineLabel(): String = when (Prefs.ocrMode()) {
        "local" -> "локальный"
        "online" -> "Google Lens"
        else -> "авто"
    }

    // ----------------------------------------------------------- windows

    private fun addOverlayWindow(view: View) {
        val lp = WindowManager.LayoutParams(
            WindowManager.LayoutParams.MATCH_PARENT,
            WindowManager.LayoutParams.MATCH_PARENT,
            WindowManager.LayoutParams.TYPE_APPLICATION_OVERLAY,
            WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE or
                WindowManager.LayoutParams.FLAG_LAYOUT_IN_SCREEN or
                WindowManager.LayoutParams.FLAG_LAYOUT_NO_LIMITS,
            PixelFormat.TRANSLUCENT,
        )
        overlayParams = lp
        wm.addView(view, lp)
        // Точное экранное смещение оверлея известно лишь после разметки —
        // ставим пузырь строго под тулбар, чтобы не перекрывать кнопки.
        view.post {
            val loc = IntArray(2)
            view.getLocationOnScreen(loc)
            if (loc[1] != 0) {
                bubbleParams?.y = loc[1] + px(44f).toInt() + px(16f).toInt()
                bubbleView?.let { runCatching { wm.updateViewLayout(it, bubbleParams) } }
            }
        }
    }

    private fun addBubbleWindow() {
        val view = object : View(this) {
            private val paint = Paint(Paint.ANTI_ALIAS_FLAG).apply { color = Color.parseColor("#E91E63") }
            private val textPaint = Paint(Paint.ANTI_ALIAS_FLAG).apply {
                color = Color.WHITE
                textAlign = Paint.Align.CENTER
                textSize = px(20f)
            }

            override fun onDraw(canvas: Canvas) {
                val c = width / 2f
                canvas.drawCircle(c, c, c, paint)
                canvas.drawText("Ч", c, c + px(7f), textPaint)
            }

            override fun onTouchEvent(event: MotionEvent): Boolean {
                if (event.actionMasked == MotionEvent.ACTION_UP) {
                    togglePassthrough()
                    return true
                }
                return super.onTouchEvent(event)
            }
        }
        val size = px(44f).toInt()
        val lp = WindowManager.LayoutParams(
            size,
            size,
            WindowManager.LayoutParams.TYPE_APPLICATION_OVERLAY,
            WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE or
                WindowManager.LayoutParams.FLAG_LAYOUT_IN_SCREEN,
            PixelFormat.TRANSLUCENT,
        ).apply {
            gravity = Gravity.TOP or Gravity.END
            x = px(8f).toInt()
            y = computeBubbleY()
        }
        bubbleParams = lp
        bubbleView = view
        wm.addView(view, lp)
    }

    /**
     * Пропуск касаний: оверлей становится невидимым и нетронутым, приложение
     * под ним полностью управляемо; вернуть читалку можно пузырём.
     */
    private fun setPassthrough(on: Boolean) {
        val v = overlay ?: return
        val lp = overlayParams ?: return
        if (on) {
            v.visibility = View.INVISIBLE
            lp.flags = lp.flags or WindowManager.LayoutParams.FLAG_NOT_TOUCHABLE
        } else {
            v.visibility = View.VISIBLE
            lp.flags = lp.flags and WindowManager.LayoutParams.FLAG_NOT_TOUCHABLE.inv()
        }
        runCatching { wm.updateViewLayout(v, lp) }
    }

    private fun togglePassthrough() {
        val currentlyHidden = overlay?.visibility != View.VISIBLE
        setPassthrough(!currentlyHidden)
    }

    private fun computeBubbleY(): Int {
        val toolbarH = px(44f)
        return toolbarH.toInt() + px(12f).toInt()
    }

    private fun px(v: Float): Float = v * resources.displayMetrics.density

    // ----------------------------------------------------------- teardown

    private fun stopEverything() {
        Log.i(TAG, "stopping overlay reader")
        try {
            bubbleView?.let { wm.removeView(it) }
        } catch (_: Exception) {
        }
        try {
            overlay?.let { wm.removeView(it) }
        } catch (_: Exception) {
        }
        bubbleView = null
        overlay = null
        tts?.shutdown()
        tts = null
        capture?.stop()
        capture = null
        projection = null
        stopSelf()
    }

    override fun onDestroy() {
        stopEverything()
        ocrManager.close()
        scope.cancel()
        super.onDestroy()
    }

    // ----------------------------------------------------------- notification

    private fun createNotification(title: String, text: String) {
        val manager = getSystemService(Context.NOTIFICATION_SERVICE) as NotificationManager
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {
            manager.createNotificationChannel(
                NotificationChannel(CHANNEL_ID, "Overlay Reader", NotificationManager.IMPORTANCE_LOW),
            )
        }
        val openIntent = Intent(this, MainActivity::class.java)
        val pending = PendingIntent.getActivity(
            this,
            0,
            openIntent,
            PendingIntent.FLAG_IMMUTABLE or PendingIntent.FLAG_UPDATE_CURRENT,
        )
        val notification: Notification = if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {
            Notification.Builder(this, CHANNEL_ID)
                .setContentTitle(title)
                .setContentText(text)
                .setSmallIcon(R.drawable.ic_notification)
                .setContentIntent(pending)
                .setOngoing(true)
                .build()
        } else {
            @Suppress("DEPRECATION")
            Notification.Builder(this)
                .setContentTitle(title)
                .setContentText(text)
                .setSmallIcon(R.drawable.ic_notification)
                .setContentIntent(pending)
                .setOngoing(true)
                .build()
        }
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.Q) {
            startForeground(
                NOTIFICATION_ID,
                notification,
                ServiceInfo.FOREGROUND_SERVICE_TYPE_MEDIA_PROJECTION,
            )
        } else {
            startForeground(NOTIFICATION_ID, notification)
        }
    }

    override fun onBind(intent: Intent?): IBinder? = null

    companion object {
        private const val TAG = "OverlayReader"
        const val ACTION_START = "com.yomikai.overlayreader.START"
        const val ACTION_STOP = "com.yomikai.overlayreader.STOP"
        const val EXTRA_RESULT_CODE = "result_code"
        const val EXTRA_DATA = "data"

        private const val CHANNEL_ID = "overlay_reader_channel"
        private const val NOTIFICATION_ID = 42

        fun start(context: Context, resultCode: Int, data: Intent) {
            val intent = Intent(context, OverlayReaderService::class.java).apply {
                action = ACTION_START
                putExtra(EXTRA_RESULT_CODE, resultCode)
                putExtra(EXTRA_DATA, data)
            }
            context.startForegroundService(intent)
        }

        fun stop(context: Context) {
            Intent(context, OverlayReaderService::class.java).apply {
                action = ACTION_STOP
                context.startService(this)
            }
        }
    }
}

