package com.yomikai.overlayreader

import android.content.Context
import android.content.SharedPreferences

/**
 * Простые сохранённые настройки читалки: положение/размер рамки зампинга,
 * выбранный движок, настройки озвучки.
 *
 * Всё хранится во float/boolean/string — не требует Android-инфраструктуры и
 * переживает перезапуск сервиса поверх любого приложения.
 */
object Prefs {

    private const val NAME = "overlay_reader"

    private lateinit var sp: SharedPreferences

    fun init(context: Context) {
        sp = context.applicationContext.getSharedPreferences(NAME, Context.MODE_PRIVATE)
    }

    // ---- Рамка захвата (в долях экрана 0..1) ----
    fun frame() = RectFBean(
        left = sp.getFloat("frame_left", 0.06f),
        top = sp.getFloat("frame_top", 0.16f),
        right = sp.getFloat("frame_right", 0.94f),
        bottom = sp.getFloat("frame_bottom", 0.55f),
    )

    fun saveFrame(f: RectFBean) {
        sp.edit()
            .putFloat("frame_left", f.left)
            .putFloat("frame_top", f.top)
            .putFloat("frame_right", f.right)
            .putFloat("frame_bottom", f.bottom)
            .apply()
    }

    // ---- Движок OCR: "auto" | "local" | "online" ----
    fun ocrMode(): String = sp.getString("ocr_mode", "auto") ?: "auto"

    fun setOcrMode(value: String) {
        sp.edit().putString("ocr_mode", value).apply()
    }

    // ---- Озвучка ----
    fun autoTts(): Boolean = sp.getBoolean("auto_tts", true)

    fun setAutoTts(value: Boolean) {
        sp.edit().putBoolean("auto_tts", value).apply()
    }

    fun ttsVoiceIndex(): Int = sp.getInt("tts_voice_index", 0)

    fun setTtsVoiceIndex(value: Int) {
        sp.edit().putInt("tts_voice_index", value).apply()
    }

    // ---- Прочее UI ----
    fun overlayOpacity(): Float = sp.getFloat("overlay_opacity", 0.32f)

    fun setOverlayOpacity(value: Float) {
        sp.edit().putFloat("overlay_opacity", value).apply()
    }

    fun hiddenUntilTap(): Boolean = sp.getBoolean("hidden_until_tap", false)
}

/** Прямоугольник рамки в долях 0..1. */
data class RectFBean(
    val left: Float,
    val top: Float,
    val right: Float,
    val bottom: Float,
) {
    val width: Float get() = (right - left).coerceAtLeast(0.1f)
    val height: Float get() = (bottom - top).coerceAtLeast(0.1f)
}

package com.yomikai.overlayreader

import android.content.Context
import android.graphics.Bitmap
import android.graphics.PixelFormat
import android.graphics.Rect
import android.hardware.display.DisplayManager
import android.hardware.display.VirtualDisplay
import android.media.ImageReader
import android.os.Handler
import android.os.HandlerThread
import android.util.DisplayMetrics
import android.util.Log
import android.view.WindowManager

/**
 * Захват экрана через MediaProjection и вырезание рамки.
 *
 * VirtualDisplay создаётся один раз и держится до остановки — это
 * единственный надёжный путь на Android 14+, где пересоздание дисплеев
 * одноразовыми проекциями запрещено.
 */
class CaptureEngine(
    context: Context,
    private val projection: android.media.projection.MediaProjection,
) {
    private val appContext = context.applicationContext

    private var thread: HandlerThread? = null
    private var handler: Handler? = null
    private var reader: ImageReader? = null
    private var display: VirtualDisplay? = null
    private var sizeW: Int = 0
    private var sizeH: Int = 0
    private var density: Int = 0

    /** Размер захватываемого экрана в px (актуальны после первого capture). */
    var screenWidth: Int = 0
        private set
    var screenHeight: Int = 0
        private set

    /** Захватить текущий кадр и вернуть битмап области [rect] (в экранных px). */
    fun capture(rect: Rect): Bitmap? {
        if (display == null && !ensureStarted()) return null

        // Статичный экран может долго не порождать новых кадров (AUTO_MIRROR
        // отрисовывает только «грязные» области) — крутимся до 3 секунд.
        val succeedAt = System.currentTimeMillis() + 3000
        var image: android.media.Image? = null
        while (image == null && System.currentTimeMillis() < succeedAt) {
            image = reader?.acquireLatestImage()
            if (image == null) Thread.sleep(120)
        }
        val img = image ?: return null
        return try {
            val full = copyImage(img) ?: return null
            try {
                val left = rect.left.coerceIn(0, full.width - 1)
                val top = rect.top.coerceIn(0, full.height - 1)
                val right = rect.right.coerceIn(left + 1, full.width)
                val bottom = rect.bottom.coerceIn(top + 1, full.height)
                Bitmap.createBitmap(full, left, top, right - left, bottom - top)
            } finally {
                if (!full.isRecycled) full.recycle()
            }
        } finally {
            img.close()
        }
    }

    private fun ensureStarted(): Boolean {
        if (display != null && reader != null) return true
        // Предыдущая попытка могла упасть уже после создания ImageReader:
        // тогда reader остался не-null, а display — null, и ensureStarted()
        // больше никогда не доходил до createVirtualDisplay (захват умирал
        // навсегда). Перед повтором разбираем half-initialized состояние.
        releaseCaptureResources()

        val metrics = DisplayMetrics()
        appContext.getSystemService(Context.WINDOW_SERVICE)
            .let { (it as WindowManager) }
            .defaultDisplay
            .getRealMetrics(metrics)
        sizeW = metrics.widthPixels
        sizeH = metrics.heightPixels
        density = metrics.densityDpi
        screenWidth = sizeW
        screenHeight = sizeH
        if (sizeW <= 0 || sizeH <= 0) return false

        thread = HandlerThread("overlay_capture").also { it.start() }
        handler = Handler(thread!!.looper)
        reader = ImageReader.newInstance(sizeW, sizeH, PixelFormat.RGBA_8888, 2)
        display = try {
            projection.createVirtualDisplay(
                "overlay_reader_capture",
                sizeW,
                sizeH,
                density,
                DisplayManager.VIRTUAL_DISPLAY_FLAG_AUTO_MIRROR,
                reader!!.surface,
                null,
                handler,
            )
        } catch (e: Exception) {
            Log.e("OverlayCapture", "createVirtualDisplay failed", e)
            null
        }
        if (display == null) {
            // Чистим за собой, чтобы следующий capture() честно попробовал снова.
            releaseCaptureResources()
        }
        return display != null
    }

    /**
     * Гасит только собственные ресурсы захвата. MediaProjection не трогаем:
     * она принадлежит сервису, и её остановка погасила бы всю сессию.
     */
    private fun releaseCaptureResources() {
        runCatching { display?.release() }
        runCatching { reader?.close() }
        display = null
        reader = null
        handler?.looper?.quitSafely()
        thread?.join(500)
        thread = null
        handler = null
    }

    private fun copyImage(image: android.media.Image): Bitmap? {
        val plane = image.planes[0]
        val buffer = plane.buffer
        val pixelStride = plane.pixelStride
        val rowStride = plane.rowStride
        val rowPadding = rowStride - pixelStride * image.width
        if (rowPadding < 0) return null

        val aux = Bitmap.createBitmap(
            image.width + rowPadding / pixelStride,
            image.height,
            Bitmap.Config.ARGB_8888,
        )
        aux.copyPixelsFromBuffer(buffer)
        val bmp = Bitmap.createBitmap(aux, 0, 0, image.width, image.height)
        if (!aux.isRecycled) aux.recycle()
        return bmp
    }

    fun stop() {
        releaseCaptureResources()
        runCatching { projection.stop() }
    }
}

